<?php
declare(strict_types=1);
namespace Amanah\SEOEngine\Infrastructure\Repository;
use Amanah\SEOEngine\Application\Repository\IntelligenceFindingRepositoryInterface;
use Amanah\SEOEngine\Domain\ContentIntelligence\IntelligenceFinding;
defined('ABSPATH') || exit;
final class WordPressIntelligenceFindingRepository extends WordPressRepository implements IntelligenceFindingRepositoryInterface {
 public function __construct(\wpdb $wpdb){parent::__construct($wpdb,$wpdb->prefix.'amanah_seo_intelligence_findings');}
 public function findByKey(string $key):?IntelligenceFinding{$r=$this->wpdb->get_row($this->wpdb->prepare("SELECT * FROM {$this->table} WHERE finding_key=%s LIMIT 1",$key),ARRAY_A);return $this->hydrate($r);}
 public function findByRunId(int $run_id):array{$rows=$this->wpdb->get_results($this->wpdb->prepare("SELECT * FROM {$this->table} WHERE intelligence_run_id=%d ORDER BY id ASC",$run_id),ARRAY_A);return array_values(array_filter(array_map(array($this,'hydrate'),is_array($rows)?$rows:array())));}
 public function save(IntelligenceFinding $f):IntelligenceFinding{$data=array('intelligence_run_id'=>$f->getRunId(),'finding_key'=>$f->getKey(),'finding_type'=>$f->getType(),'subject'=>$f->getSubject(),'description'=>$f->getDescription(),'evidence'=>wp_json_encode($f->getEvidence()),'source'=>$f->getSource(),'materiality'=>$f->getMateriality(),'confidence'=>$f->getConfidence(),'status'=>$f->getStatus(),'updated_at'=>current_time('mysql',true));$formats=array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s');$existing=$this->findByKey($f->getKey());if(null!==$existing){$this->wpdb->update($this->table,$data,array('id'=>$existing->getId()),$formats,array('%d'));return new IntelligenceFinding((int)$existing->getRunId(),$existing->getKey(),$existing->getType(),$existing->getSubject(),$existing->getDescription(),$existing->getEvidence(),$existing->getSource(),$existing->getMateriality(),$existing->getConfidence(),$existing->getStatus(),$existing->getId());}$data['created_at']=current_time('mysql',true);if(false===$this->wpdb->insert($this->table,$data,$formats+array('%s')))throw new \RuntimeException('Intelligence finding could not be stored.');return new IntelligenceFinding($f->getRunId(),$f->getKey(),$f->getType(),$f->getSubject(),$f->getDescription(),$f->getEvidence(),$f->getSource(),$f->getMateriality(),$f->getConfidence(),$f->getStatus(),(int)$this->wpdb->insert_id);}
 private function hydrate($r):?IntelligenceFinding{if(!is_array($r))return null;$e=json_decode((string)$r['evidence'],true);return new IntelligenceFinding((int)$r['intelligence_run_id'],(string)$r['finding_key'],(string)$r['finding_type'],(string)$r['subject'],(string)$r['description'],is_array($e)?$e:array(),(string)$r['source'],(string)$r['materiality'],(string)$r['confidence'],(string)$r['status'],(int)$r['id']);}
}